const REAL=Math.floor((Date.now()+9*3600e3)/864e5);
const KEY='semharu-v7';
function load(){ return env.load(); }
function save(){ env.save(S); }
const today=()=>REAL+S.offset;
const DOW=['일','월','화','수','목','금','토'];
function dlabel(d){ const t=new Date(d*864e5); return `${t.getUTCMonth()+1}/${t.getUTCDate()}(${DOW[t.getUTCDay()]})`; }
function rel(d){ const k=d-today(); return k<=0?(k<0?`${-k}일 밀림`:'오늘'):k===1?'내일':`${k}일 뒤`; }

/* ---------- 예시 데이터 ---------- */
function seed(){
  const t=REAL; let rs=20261020; const rnd=()=>{rs=(rs*16807)%2147483647;return rs/2147483647;}; const ri=(a,b)=>a+Math.floor(rnd()*(b-a+1));
  const mk=(id,cur,name,age,color,grad,cardSpec,skip)=>{
    const ids=STAGES.slice(0,IDX[cur]).map(s=>s.id);
    const passed={}, read={}, sst={}, stat={};
    ids.forEach((sid,i)=>{ passed[sid]={due:t+((i*7)%6)-1}; read[sid]=true; sst[sid]=[ri(70,95),ri(75,100),ri(80,100)];
      const ar=STAGES[IDX[sid]].area, n=ri(20,40); stat[ar]=stat[ar]||{n:0,c:0}; stat[ar].n+=n; stat[ar].c+=Math.round(n*(0.8+rnd()*0.17)); });
    const hist={};
    for(let d=0;d<29;d++){ if(skip.includes(d%7)&&rnd()<.8) continue; const n=ri(20,26); hist[t-29+d]={n,c:Math.round(n*(0.72+rnd()*0.22)),ms:n*ri(28,52)*1000}; }
    const cards=cardSpec.map(([sid,k,box,due,w])=>{ const q=BANK[sid][k%BANK[sid].length]; return {id:sid+'-'+k,q:q.q,a:q.a,st:sid,box,due:t+due,wrong:w}; });
    return {id,name,age,color,stage:IDX[cur],streak:0,grad,read,passed,sst,stat,hist,cards,bp:{[cur]:0}};
  };
  return {offset:0,active:'minwang',profiles:{
    minwang:mk('minwang','f11','민왕','초5','#0FA37F',37,[['f9',2,0,-2,3],['f8',5,0,-1,2],['f7',1,1,0,2],['n28',3,0,0,1],['n27',4,2,0,2],['f10',6,1,1,1],['f2',7,0,2,1],['n18',0,1,3,4]],[2,5]),
    seoyun:mk('seoyun','n24','서윤','초3','#7FD6B9',19,[['n18',3,0,-1,3],['n17',2,1,0,2],['n13',5,0,0,2],['n13',1,2,0,1],['n22',4,0,1,1],['n23',6,1,4,1]],[1,4])
  }};
}
let S=load()||env.fresh();
const P=()=>S.profiles[S.active];

/* ---------- 채점 ---------- */
function val(s){ s=String(s).replace('−','-'); if(s.includes('/')){const [n,d]=s.split('/').map(Number);return d?n/d:NaN;} return parseFloat(s); }
function judge(input,ans){
  const v=val(input); if(isNaN(v)) return {ok:false};
  if(Math.abs(v-val(ans))>1e-9) return {ok:false};
  if(input.includes('/')){ const [n,d]=input.split('/').map(Number); if(gcd(n,d)>1||d===1) return {ok:false,msg:'값은 맞지만 기약분수로 써야 해요'}; }
  if(ans.includes('/')&&!input.includes('/')) return {ok:false,msg:'분수로 답해 주세요'};
  return {ok:true};
}
const show=a=> a.includes('/')?(a.startsWith('-')?'−'+fr(...a.slice(1).split('/')):fr(...a.split('/'))):a.replace('-','−');
const plain=q=>q.replace(/<small>.*<\/small>/,'').replace('<br>',' ');

/* ---------- 세트 구성 ---------- */
function dueCards(p){ return p.cards.filter(c=>c.due<=today()).sort((a,b)=>(a.due-b.due)||(b.wrong-a.wrong)); }
function dueStages(p){ return Object.entries(p.passed).filter(([,v])=>v.due<=today()).sort((a,b)=>a[1].due-b[1].due).map(([id])=>id); }
function warm(p,rv){ const b=Object.keys(p.passed).filter(id=>IDX[id]!=null&&/초[123]/.test(STAGES[IDX[id]].g)&&!rv.includes(id)); const o=[]; for(let k=0;k<2&&b.length;k++) o.push(b.splice(Math.floor(Math.random()*b.length),1)[0]); return o; }
function plan(p){ const cards=dueCards(p).slice(0,10), rv0=dueStages(p).slice(0,3), rv=[...rv0.flatMap(id=>[id,id]),...warm(p,rv0)]; return {cards,rv,n:Math.max(4,SET-cards.length-rv.length),late:p.cards.filter(c=>c.due<today()).length}; }
function buildQueue(p,mode,arg){
  if(mode==='today'){ const pl=plan(p); return [...pl.cards.map(c=>({src:'card',card:c})),...pl.rv.map(id=>({src:'review',st:id})),...Array.from({length:pl.n},()=>({src:'new'}))]; }
  if(mode==='cards') return [...dueCards(p),...p.cards.filter(c=>c.due>today())].slice(0,15).map(c=>({src:'card',card:c}));
  if(mode==='new') return Array.from({length:10},()=>({src:'new'}));
  if(mode==='stage') return Array.from({length:10},()=>({src:'review',st:arg}));
}
function resolve(it,p){
  if(it.src==='card') return {q:it.card.q,a:it.card.a,st:it.card.st};
  if(it.src==='retry') return {q:it.q,a:it.a,st:it.st};
  const st=it.src==='new'?STAGES[p.stage].id:it.st, b=BANK[st];
  if(!b||!b.length) return {...STAGES[IDX[st]].gen(),st};
  if(it.src==='new'){ p.bp=p.bp||{}; const k=Math.min(p.bp[st]||0,b.length-1); const item=k>=b.length-1?b[b.length-1-Math.floor(Math.random()*Math.ceil(b.length/3))]:b[k]; return {...item,st,pos:k}; }
  return {...pick(b),st};
}
function addCard(p,pr){
  const ex=p.cards.find(c=>c.q===pr.q); if(ex){ex.box=0;ex.due=today()+1;ex.wrong++;return;}
  p.cards.push({id:Math.random().toString(36).slice(2,8),q:pr.q,a:pr.a,st:pr.st,box:0,due:today()+1,wrong:1});
}

/* ---------- 단계별 최근 평균 (최근 3회 세트 점수) ---------- */
function ensureSst(){
  Object.values(S.profiles).forEach(p=>{
    if(p.sst) return; p.sst={};
    Object.keys(p.passed).forEach((id,i)=>{ p.sst[id]=[80+((i*7)%20), 85+((i*11)%15), 90+((i*3)%10)]; });
  });
}
Object.values(S.profiles).forEach(p=>Object.values(p.hist).forEach(h=>{ if(h.n&&h.ms===undefined) h.ms=h.n*42000; }));
ensureSst();
const avg=id=>{ const a=P().sst[id]; return a&&a.length ? (a.reduce((x,y)=>x+y,0)/a.length).toFixed(1) : '0.0'; };

/* ---------- 틀 ---------- */
const bar=root.querySelector('#bar'), screen=root.querySelector('#screen'), tabs=root.querySelector('#tabs');
let tab='home', G=null, areaF=null;
const LI=(n,c)=>`<i data-lucide="${n}"${c?` class="${c}"`:''}></i>`;
const IC={list:LI('list-checks'),clock:LI('clock'),check:LI('circle-check-big')};
function mmS(ms){ const m=Math.round((ms||0)/60000); return m<60?`${m}분`:`${Math.floor(m/60)}시간 ${m%60}분`; }
function ring(pct,big,sub,col){ const r=52,C=2*Math.PI*r,d=Math.max(0,Math.min(1,pct))*C;
  return `<svg viewBox="0 0 140 140" class="ring" role="img" aria-label="${big} ${sub}"><circle cx="70" cy="70" r="${r}" fill="none" stroke="var(--hi)" stroke-width="12"/><circle cx="70" cy="70" r="${r}" fill="none" stroke="${col||'var(--y)'}" stroke-width="12" stroke-linecap="round" stroke-dasharray="${d} ${C}" transform="rotate(-90 70 70)"/><text x="70" y="72" text-anchor="middle" font-size="30" font-weight="900" fill="var(--k)">${big}</text><text x="70" y="94" text-anchor="middle" font-size="11.5" fill="var(--sub)">${sub}</text></svg>`; }
const Q_ICON='<span class="pillq">개념</span>';
function askQuit(fn){ const app=root.querySelector('.app'); app.querySelector('#qdlg')?.remove();
  app.insertAdjacentHTML('beforeend','<div class="dim" id="qdlg"><div class="dialog" role="alertdialog" aria-labelledby="qt"><h3 id="qt">그만할까요?</h3><p>지금까지 푼 문제는 저장돼요. 오늘 학습에서 이어서 할 수 있어요.</p><div class="qrow"><button class="qno" data-q="no">계속하기</button><button data-q="yes">그만하기</button></div></div></div>');
  const d=app.querySelector('#qdlg'); d.onclick=e=>{ const q=e.target.closest('[data-q]')?.dataset.q; if(e.target===d||q==='no') d.remove(); else if(q==='yes'){ d.remove(); fn(); } }; }
function setBar(title,{back,help,quit}={}){
  const p=P();
  bar.innerHTML=`${back?`<button class="bb" id="bBack" aria-label="${quit?'그만하기':'뒤로'}">${LI(quit?'x':'arrow-left')}</button>`
    :`<button class="bb who" id="bWho" aria-label="학생 바꾸기">${LI('user-round')}${p.name}<small>${p.age}</small>${LI('chevrons-up-down','sm')}</button>`}
    <h1>${title}</h1>${help?`<button class="bb" id="bHelp" aria-label="개념 보기">${LI('circle-help')}</button>`:'<span class="bb"></span>'}`;
  if(back) bar.querySelector('#bBack').onclick=quit?()=>askQuit(back):back;
  else bar.querySelector('#bWho').onclick=()=>env.switchKid();
  if(help) bar.querySelector('#bHelp').onclick=help;
}
function showTabs(on){
  tabs.hidden=!on;
  if(!on) return;
  tabs.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.tab===tab));
  const n=dueCards(P()).length, b=tabs.querySelector('[data-tab="cards"]');
  b.querySelector('.dot')?.remove(); if(n) b.insertAdjacentHTML('beforeend',`<span class="dot">${n}</span>`);
}
function setTab(t){ tab=t; G=null; document.onkeydown=null; render(); screen.scrollTop=0; }
function render(){ showTabs(true); ({home:renderHome,cards:renderCards,report:renderReport})[tab](); }

/* ---------- 연산학습 (홈) ---------- */
function renderHome(){
  const p=P(), pl=plan(p), total=pl.cards.length+pl.rv.length+pl.n, done=Math.min((p.hist[today()]||{}).n||0,total);
  const cur=STAGES[p.stage]; if(!areaF) areaF=cur.area;
  setBar('연산학습');
  const list=STAGES.map((s,i)=>({...s,i})).filter(s=>s.area===areaF);
  const th=p.hist[today()]||{n:0,c:0,ms:0};
  screen.innerHTML=`
    <section class="sec">
      <div class="hrow"><span class="badge">TODAY</span><span class="sub">${dlabel(today())} · ${p.name}의 학습</span></div>
      <div class="paycard">
        <div class="pc-top"><span class="pc-logo">${LI('calculator')}</span><b>오늘 학습</b>${pl.late?`<span class="latepill">밀린 학습 ${pl.late}건</span>`:''}<div class="pc-amt">${done}<small> / ${total}문제</small></div></div>
        <p class="mixline">오답 다시 <b>${pl.cards.length}</b> · 단계 복습 <b>${pl.rv.length}</b> · 새 진도 <b>${pl.n}</b></p>
        <div class="pc-btns"><button class="gbtn" id="goCards">오답만</button><button class="gbtn" id="goNew">진도만</button><button class="kbtn" id="go">${LI('play')}${done?'이어서':'시작'}</button></div>
      </div>
    </section>
    <section class="sec">
      <h3 class="sh">오늘 기록</h3>
      <div class="stat3">
        <div><span class="ic">${IC.list}</span><b>${th.n}개</b><small>푼 문제</small></div>
        <div><span class="ic">${IC.clock}</span><b>${mmS(th.ms)}</b><small>학습 시간</small></div>
        <div><span class="ic">${IC.check}</span><b>${th.n?Math.round(th.c/th.n*100):0}%</b><small>정답률</small></div>
      </div>
    </section>
    <section class="sec">
      <h3 class="sh">지금 단계 <small>${cur.g} · ${p.stage+1}/${STAGES.length}단계</small></h3>
      <div class="nowrow">
        <span class="lic s-now">${LI('pencil')}</span>
        <div class="nr-body"><b>${cur.name}</b>
          <span class="streak">${p.read[cur.id]?Array.from({length:GOAL},(_,i)=>`<i class="${i<p.streak?'on':''}"></i>`).join('')+`<em>연속 ${p.streak}/${GOAL} · 틀림 ${WR(p,cur.id)}/${CAP(cur)}</em>`:`<em>개념 설명을 먼저 읽어요 · ${CAP(cur)}개 틀리면 처음부터</em>`}</span></div>
        <button class="qbtn" data-q="${cur.id}" aria-label="${cur.name} 개념">${Q_ICON}</button>
      </div>
    </section>
    <section class="sec flush">
      <h3 class="sh pad16">단원 목록</h3>
    <div class="areas">${AREAS.map(a=>{const ss=STAGES.filter(s=>s.area===a);const n=ss.filter(s=>p.passed[s.id]).length;return `<button class="chip ${a===areaF?'on':''}" data-af="${a}">${a} <small>${n}/${ss.length}</small></button>`;}).join('')}</div>
    <ul class="units">${list.map(s=>{
      const ps=p.passed[s.id], now=s.i===p.stage, lock=!ps&&!now, due=ps&&ps.due<=today();
      const st=ps?(due?`<span class="tag due">${LI('repeat')}복습 차례</span>`:`<span class="tag ok">${LI('check')}통과</span>`):now?`<span class="tag nowt">${LI('pencil')}학습 중</span>`:`<span class="tag lk">${LI('lock')}잠김</span>`;
      const sub=ps?`최근 평균 ${avg(s.id)} · 다음 복습 ${rel(ps.due)}`:now?`난이도 ${LV(s.id,p)} · 문제 ${((p.bp||{})[s.id]||0)+1}/${BANK[s.id].length} · 연속 ${p.streak}/${GOAL}`:`${s.g} · 예) ${s.ex}`;
      const li=ps?(due?`<span class="lic s-due">${LI('repeat')}</span>`:`<span class="lic s-ok">${LI('check')}</span>`):now?`<span class="lic s-now">${LI('pencil')}</span>`:`<span class="lic s-lk">${LI('lock')}</span>`;
      return `<li class="${now?'cur':''} ${lock?'lock':''}">${li}<button class="unit" data-st="${s.id}" ${lock?'disabled':''}><b>${s.name}</b><small>${sub}</small></button>${st}<button class="qbtn" data-q="${s.id}" aria-label="${s.name} 개념">${Q_ICON}</button></li>`;}).join('')}</ul>
    </section>
    <p class="note">한 단계에서 정해진 개수(초1~2 5개 · 초3~4 6개 · 초5~6 7개 · 중등 이상 8개)를 틀리면 그 단계를 개념부터 처음부터 다시 해요. 민왕(초5)·서윤(초3)과 그동안의 기록은 예시 데이터예요. 학습결과 탭에서 하루를 넘겨 1·3·5일 반복을 시연할 수 있어요.</p>`;
  screen.querySelector('#go').onclick=()=>start('today','오늘 학습');
  screen.querySelector('#goCards').onclick=()=>{ if(P().cards.length) start('cards','오답 다시'); };
  screen.querySelector('#goNew').onclick=()=>start('new',STAGES[P().stage].name);
  screen.querySelectorAll('[data-sc]').forEach(b=>b.onclick=()=>{ const k=b.dataset.sc;
    if(k==='cards'||k==='report') setTab(k);
    else if(k==='concept') openConcept(STAGES[P().stage].id,()=>render());
    else env.switchKid(); });
  screen.querySelectorAll('[data-af]').forEach(b=>b.onclick=()=>{areaF=b.dataset.af;renderHome();});
  screen.querySelectorAll('.unit:not(:disabled)').forEach(b=>b.onclick=()=>{
    const id=b.dataset.st; if(IDX[id]===P().stage) start('new',STAGES[IDX[id]].name); else start('stage',STAGES[IDX[id]].name,id);
  });
  screen.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>openConcept(b.dataset.q,()=>render()));
}
function openConcept(id,back){
  const p=P(), i=IDX[id], unlocked=p.passed[id]||i===p.stage;
  concept(id,false,back, unlocked?()=>{ if(i===p.stage) start('new',STAGES[i].name); else start('stage',STAGES[i].name,id); }:null);
}

/* ---------- 오답노트 ---------- */
function renderCards(){
  const p=P(), t=today();
  setBar('오답노트');
  const cal=Array.from({length:7},(_,i)=>{const d=t+i;const n=p.cards.filter(c=>i===0?c.due<=d:c.due===d).length;return `<div class="${i===0&&n?'t':''}"><span>${i===0?'오늘':DOW[new Date(d*864e5).getUTCDay()]}</span><b>${n}</b></div>`;}).join('');
  const sorted=[...p.cards].sort((a,b)=>(a.due-b.due)||(b.wrong-a.wrong));
  screen.innerHTML=`
    <section class="card"><div class="todaycard">
      <h2>오늘 다시 풀 오답 <small>틀리면 1일 → 3일 → 5일 뒤</small></h2>
      <div class="cols"><div><small>오늘</small><b class="${dueCards(p).length?'red':''}">${dueCards(p).length}건</b></div><div><small>전체 / 졸업</small><b>${p.cards.length} / ${p.grad}</b></div></div>
      <button class="startbtn" id="go" ${p.cards.length?'':'disabled'}>${LI('rotate-ccw')}오답만 풀기</button></div></section>
    <div class="box"><h3>다시 나오는 날</h3><div class="cal">${cal}</div><p class="note">세 번 연속 맞히면 졸업, 중간에 틀리면 1일로 돌아가요.</p></div>
    <ul class="units">${sorted.length?sorted.map(c=>`<li><div class="unit static"><b class="mq">${plain(c.q)} = <span class="ansv">${show(c.a)}</span></b>
      <small><span class="x">✕${c.wrong}</span> · ${STAGES[IDX[c.st]].name} · <span class="${c.due<=t?'x':''}">${rel(c.due)}</span> · 졸업까지 ${3-c.box}번</small></div>
      <button class="qbtn" data-q="${c.st}" aria-label="개념">${Q_ICON}</button></li>`).join(''):'<li><div class="unit static"><b>오답이 없어요</b><small>전부 졸업했어요</small></div></li>'}</ul>`;
  screen.querySelector('#go').onclick=()=>{ if(P().cards.length) start('cards','오답 다시'); };
  screen.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>openConcept(b.dataset.q,()=>render()));
}

/* ---------- 리포트 (일별·주간·월간) ---------- */
let rmode='day', rshift=0;
function renderReport(){
  const p=P(), t=today();
  setBar('학습결과');
  const span=rmode==='day'?1:rmode==='week'?7:30;
  const endD=t-rshift*span, days=Array.from({length:span},(_,i)=>endD-span+1+i);
  const hs=days.map(d=>p.hist[d]||{n:0,c:0,ms:0});
  const tot=hs.reduce((a,h)=>({n:a.n+h.n,c:a.c+h.c,ms:a.ms+(h.ms||0)}),{n:0,c:0,ms:0});
  const att=hs.filter(h=>h.n).length, rate=tot.n?Math.round(tot.c/tot.n*100):0;
  const label=rmode==='day'?dlabel(endD):`${dlabel(days[0])} ~ ${dlabel(endD)}`;
  const goalN=SET*span, goalMs=span*15*60000;
  const by={}; p.cards.forEach(c=>{by[c.st]=(by[c.st]||0)+c.wrong;});
  const worst=Object.entries(by).sort((a,b)=>b[1]-a[1]).slice(0,3);
  const mx=Math.max(SET,...hs.map(h=>h.n));
  screen.innerHTML=`
    <div class="seg">${[['day','일별 보고서'],['week','주간 보고서'],['month','월간 보고서']].map(([k,l])=>`<button data-rm="${k}" class="${k===rmode?'on':''}">${l}</button>`).join('')}</div>
    <div class="datenav"><button id="prevD" aria-label="이전">${LI('chevron-left')}</button><span>${label}</span><button id="nextD" aria-label="다음" ${rshift===0?'disabled':''}>${LI('chevron-right')}</button></div>
    <div class="ringrow">
    <section class="card center">
      ${ring(tot.n/goalN, tot.n+'개','총 문제 개수')}
      <div class="legend"><span><i style="background:var(--y)"></i>정답 ${tot.c}개</span><span><i style="background:var(--red)"></i>오답 ${tot.n-tot.c}개</span><span>정답률 ${rate}%</span></div>
    </section>
    <section class="card center">
      ${ring(tot.ms/goalMs, mmS(tot.ms),'총 학습 시간','var(--k)')}
      <p class="note">${rmode==='day'?'하루 목표 15분':`${span}일 중 ${att}일 출석 · 하루 목표 15분`}</p>
    </section>
    </div>
    <section class="card wkme"><h3>이번 주 기록</h3><div class="wkt">${env.weekOk()}</div></section>
    ${rmode!=='day'?`<section class="card"><h3>하루 푼 문제</h3>
      <div class="week ${rmode}">${hs.map((h,i)=>`<div><small>${rmode==='week'&&h.n?h.n:''}</small><i class="${days[i]===t?'td':''}" style="height:${h.n/mx*100}%"></i></div>`).join('')}</div>
      ${rmode==='week'?`<div class="days">${days.map(d=>`<span>${d===t?'오늘':DOW[new Date(d*864e5).getUTCDay()]}</span>`).join('')}</div>`:''}</section>`:''}
    <section class="card"><h3>영역별 정답률 <small class="note">누적</small></h3>${AREAS.map(a=>{const s=p.stat[a]||{n:0,c:0};const r=s.n?Math.round(s.c/s.n*100):0;return `<div class="hbar"><span>${a}</span><div class="tr"><i style="width:${r}%"></i></div><span class="v">${s.n?r+'%':'—'}</span></div>`;}).join('')}</section>
    <section class="card"><h3>많이 틀리는 단계</h3><div class="list">${worst.length?worst.map(([id,w])=>`<div><span>${STAGES[IDX[id]].g} ${STAGES[IDX[id]].name}</span><span class="x">✕${w}</span></div>`).join(''):'<p class="note">틀린 문제가 없어요.</p>'}</div></section>
    <button class="share" id="share">${LI('message-circle')}카카오톡으로 보고서 보내기</button>
    <p class="note" id="shareNote">공유는 출시 버전에서 동작해요. 지금은 보낼 문구를 복사해요.</p>
    <section class="card"><h3>시연 도구</h3><p class="note">하루를 넘기면 1·3·5일 뒤 오답과 3~5일 단계 복습이 다시 나와요.</p>
      <div class="btns"><button class="btn k" id="nextDay">${LI('calendar-plus')}하루 넘기기</button><button class="btn" id="reset">${LI('rotate-ccw')}예시로 되돌리기</button></div></section>`;
  screen.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{rmode=b.dataset.rm;rshift=0;renderReport();});
  screen.querySelector('#prevD').onclick=()=>{rshift++;renderReport();};
  screen.querySelector('#nextD').onclick=()=>{if(rshift>0){rshift--;renderReport();}};
  screen.querySelector('#share').onclick=async()=>{
    const txt=`[셈하루] ${p.name} ${label}: ${tot.n}문제, 정답률 ${rate}%, 학습 ${mmS(tot.ms)}. 지금 단계: ${STAGES[p.stage].name}. 남은 오답 ${p.cards.length}건.`;
    const n=screen.querySelector('#shareNote'); try{await navigator.clipboard.writeText(txt);n.textContent='복사했어요: '+txt;}catch(e){n.textContent=txt;}
  };
  screen.querySelector('#nextDay').onclick=()=>{S.offset++;save();render();};
  screen.querySelector('#reset').onclick=e=>{ if(e.currentTarget.dataset.c){S=env.fresh();ensureSst();areaF=null;save();render();} else {e.currentTarget.dataset.c=1;e.currentTarget.textContent='한 번 더 누르면 초기화';} };
}

/* ---------- 개념 설명 ---------- */
function concept(id,gate,onClose,onPractice){
  showTabs(false);
  const s=STAGES[IDX[id]], p=P();
  let i=0, shown=0; const total=s.exs.length+2;
  const draw=()=>{
    setBar(`개념 · ${s.name}`,{quit:!!(gate&&G),back:()=>{ if(gate&&G){G=null;document.onkeydown=null;} save(); onClose&&onClose(); }});
    let body='';
    if(i===0) body=`<span class="lk">${s.g} · ${s.area}</span><h2>${s.name}</h2>${s.c.map(t=>`<p>${t}</p>`).join('')}`;
    const ex=i>0&&i<total-1?s.exs[i-1]:null;
    if(ex) body=`<span class="lk">예제 ${i} / ${s.exs.length}</span><div class="ex">${ex.q}</div><ol>${ex.st.map((t,k)=>`<li class="${k<shown?'':'hide'}">${k<shown?t:'눌러서 다음 줄 보기'}</li>`).join('')}</ol>${shown>=ex.st.length?`<span class="eqa">답: ${ex.ans}</span>`:''}`;
    if(i===total-1) body=`<span class="lk">기억할 점</span><h2>${s.tip}</h2><p class="soft">${gate?`이 단계는 ${CAP(s)}개를 틀리면 처음부터 다시 해요. 이제 문제를 풀어요. 쉬운 문제부터 시작해서 잘 맞히면 점점 어려워져요. 어려운 문제까지 올라가 연속 ${GOAL}문제를 맞히면 다음 단계로 넘어가고, 틀린 문제는 오답노트에 들어가 1·3·5일 뒤 다시 나와요.`:'틀린 문제는 오답노트에 들어가 1·3·5일 뒤 다시 나와요.'}</p>`;
    const stepLocked=!!ex&&shown<ex.st.length, last=i===total-1;
    screen.innerHTML=`<div class="cx">
      <div class="steps">${[['lightbulb','개념'],...s.exs.map((_,k)=>['pencil-line','예제 '+(k+1)]),['bookmark','기억']].map(([ic,t],k)=>`<span class="${k===i?'on':k<i?'done':''}">${LI(k<i?'check':ic)}${t}</span>`).join('')}</div>
      <div class="lyric" id="ly">${body}</div>
      <div class="btns sp">
        <button class="btn" id="prev" ${i===0?'disabled':''}>${LI('chevron-left')}이전</button>
        ${last?(gate?`<button class="btn y" id="done">${LI('circle-check-big')}다 읽었어요 · 문제 풀기</button>`:`${onPractice?`<button class="btn y" id="prac">${LI('play')}이 단계 문제 풀기</button>`:''}<button class="btn k" id="done">닫기</button>`)
              :`<button class="btn k" id="next">${stepLocked?'풀이 한 줄 보기':'다음'}${LI(stepLocked?'chevron-down':'chevron-right')}</button>`}
      </div>
      ${gate?`<p class="gate">${last?'다 읽으면 문제가 열려요':`처음 들어가는 단계예요. 설명을 끝까지 넘겨야 문제가 열려요 (${i+1}/${total})`}</p>`:''}
    </div>`;
    screen.querySelector('#prev').onclick=()=>{i--;shown=0;draw();};
    const nx=screen.querySelector('#next'); if(nx) nx.onclick=()=>{ if(ex&&shown<ex.st.length) shown++; else {i++;shown=0;} draw(); };
    if(ex) screen.querySelector('#ly').onclick=()=>{ if(shown<ex.st.length){shown++;draw();} };
    const dn=screen.querySelector('#done'); if(dn) dn.onclick=()=>{ if(gate){p.read[id]=true;save();} onClose&&onClose(true); };
    const pr=screen.querySelector('#prac'); if(pr) pr.onclick=()=>onPractice();
  };
  draw();
}

/* ---------- 풀이 ---------- */
function start(mode,title,arg){
  const p=P(), q=buildQueue(p,mode,arg); if(!q.length) return;
  G={mode,title,arg,q,i:0,input:'',cur:null,t0:0,lock:false,log:[],passedNow:[],reviewed:{},toast:'',began:performance.now(),away:0,wrongWait:false};
  document.onkeydown=e=>{ if(!G) return; if(G.wrongWait){ if(e.key==='Enter') nextAfterWrong(); return; } if(!G.cur) return;
    if(/^[0-9]$/.test(e.key))press(e.key); else if(['.','/','-'].includes(e.key))press(e.key); else if(e.key==='Backspace')press('del'); else if(e.key==='Enter')press('ok'); };
  advance();
}
function advance(){
  const g=G, p=P(), it=g.q[g.i], sid=STAGES[p.stage].id;
  if(it.src==='new'&&!p.read[sid]){
    g.cur=null; const t0=performance.now();
    return concept(sid,true,ok=>{ if(ok&&G===g){ g.away+=performance.now()-t0; advance(); } else { G=null; render(); } });
  }
  g.cur={...it,...resolve(it,p)}; g.input=''; g.t0=performance.now(); drawPlay();
}
const SRC={card:'오답 다시',review:'단계 복습',new:'새 진도',retry:'방금 틀린 문제'};
function drawPlay(){
  showTabs(false);
  const g=G,p=P(),c=g.cur,s=STAGES[IDX[c.st]];
  setBar(g.title,{quit:true,back:()=>{G=null;document.onkeydown=null;save();render();},help:()=>openFromPlay(s.id)});
  screen.innerHTML=`<div class="np">
    <div class="prog"><div class="tr"><i style="width:${g.i/g.q.length*100}%"></i></div><span>${g.i+1} / ${g.q.length}</span></div>
    ${g.toast?`<div class="toast">${g.toast}</div>`:''}
    <div class="ptag">${c.src==='new'?`<span class="lvl l-${LV(s.id,p)}">${LV(s.id,p)}</span>`:`<span class="lvl src">${SRC[c.src]}</span>`}<span>${s.g} ${s.name}${c.src==='new'?` · 연속 ${p.streak}/${GOAL} · <b class="x">틀림 ${WR(p,s.id)}/${CAP(s)}</b>`:''}</span>${wtip()}</div>
    <div class="board" id="board"><span class="fb" id="fb"></span><div class="q">${c.q}</div><div class="ans empty" id="ans"></div></div>
    <p class="tip" id="tip"></p>
    <div class="pad2" id="pad">
      <div class="padtools"><button data-k="-">${LI('minus')}음수</button><button data-k="/">${LI('slash')}분수</button><button data-k=".">${LI('dot')}소수점</button></div>
      <div class="pad">${['1','2','3','4','5','6','7','8','9','clr','0','del'].map(k=>`<button data-k="${k}" aria-label="${{del:'한 칸 지우기',clr:'전체 지우기'}[k]||k}" class="${k==='clr'?'fn':''}">${{del:LI('arrow-left'),clr:'지우기'}[k]||k}</button>`).join('')}</div>
      <button data-k="ok" class="okbtn">입력</button>
    </div>
  </div>`;
  g.toast='';
  screen.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>press(b.dataset.k));
  bindWtip();
}
function openFromPlay(id){
  const g=G; if(!g) return; clearTimeout(g.timer); const keep=g.cur, inp=g.input, wasWrong=g.wrongWait, t0=performance.now(); g.cur=null;
  concept(id,false,()=>{ if(G!==g) return; g.away+=performance.now()-t0; g.cur=keep;
    if(wasWrong) return nextAfterWrong();
    drawPlay(); g.input=inp; const a=screen.querySelector('#ans'); a.textContent=inp.replace('-','−'); a.classList.toggle('empty',!inp); });
}

/* 틀린 개수 칸: 지금 단계에서 틀린 개수(상한 대비) + 이번 학습에서 틀린 개수 */
function wrongBox(){ const g=G, p=P(); if(!g) return ''; const s=STAGES[p.stage], cap=CAP(s), w=WR(p,s.id), sw=g.log.filter(r=>!r.ok).length;
  return `<div class="wcnt ${w>=cap-1?'full':''}" id="wcnt"><div class="r1"><b>틀린 개수</b><span class="dots">${Array.from({length:cap},(_,i)=>`<i class="${i<w?'on':''}"></i>`).join('')}</span><em>${w}/${cap}</em></div><small>${cap}개 틀리면 「${s.name}」을 처음부터 다시 해요 · 이번 학습에서 <b>${sw}개</b> 틀림</small></div>`; }
function wtip(){ return `<span class="wtip"><button type="button" class="wtb" aria-label="틀린 개수 안내" aria-expanded="false">${LI('info')}</button><span class="wpop" id="wpop" role="dialog" hidden>${wrongBox()}<p class="tip">모르면 오른쪽 위 ${LI('circle-help','inl')}를 눌러 개념을 볼 수 있어요.</p></span></span>`; }
function bindWtip(){ const w=screen.querySelector('.wtip'); if(!w) return; const b=w.querySelector('.wtb'), pop=w.querySelector('.wpop');
  const set=on=>{ pop.hidden=!on; b.setAttribute('aria-expanded',on); };
  b.onclick=e=>{ e.stopPropagation(); set(pop.hidden); };
  pop.onclick=e=>e.stopPropagation();
  screen.querySelector('.np').addEventListener('click',()=>set(false)); }
function refreshWrong(){ const el=document.getElementById('wcnt'); if(el) el.outerHTML=wrongBox(); }

/* 답하면 자동으로 다음 문제: 맞히면 0.6초, 틀리면 설명을 2.5초 보여 주고 넘어감(멈추고 보기 가능) */
const AUTO_OK=600, AUTO_NO=2500, AUTO_LONG=3800;
function autoGo(ms,go){ const g=G; if(!g) return; clearTimeout(g.timer); const host=document.getElementById('autoBox');
  if(host) host.innerHTML=`<div class="autobar"><i style="animation-duration:${ms}ms"></i></div><button class="stopauto" id="stopAuto">멈추고 보기</button>`;
  g.timer=setTimeout(()=>{ if(G===g&&(g.answered||g.wrongWait)) go(); },ms);
  const st=document.getElementById('stopAuto'); if(st) st.onclick=()=>{ clearTimeout(g.timer); host.innerHTML='<small class="autonote">멈췄어요. 다 보면 다음 문제를 눌러요.</small>'; };
}
function nextAfterWrong(){ const g=G; clearTimeout(g.timer); g.wrongWait=false; g.lock=false; g.i++; if(g.i>=g.q.length) return finish(); advance(); }
function press(k){
  const g=G; if(!g||g.lock||!g.cur) return;
  if(k==='del') g.input=g.input.slice(0,-1);
  else if(k==='clr') g.input='';
  else if(k==='ok'){ if(g.input&&g.input!=='-') return check(); }
  else if(k==='-') g.input=g.input.startsWith('-')?g.input.slice(1):'-'+g.input;
  else if((k==='.'||k==='/')&&(g.input.includes(k)||!/\d$/.test(g.input))) return;
  else if(g.input.length<9) g.input+=k;
  const a=screen.querySelector('#ans'); a.textContent=g.input.replace('-','−'); a.classList.toggle('empty',!g.input);
  /* 정답 자릿수만큼 입력하면 입력 버튼 없이 바로 채점 */
  if(k!=='del'&&k!=='clr'&&g.input&&g.input!=='-'&&g.input.length>=String(g.cur.a).length&&!/[./]$/.test(g.input)) check();
}
function check(){
  const g=G,p=P(),c=g.cur,t=today(),s=STAGES[IDX[c.st]];
  const j=judge(g.input,c.a), ok=j.ok; HG(ok?'ok':'no');
  p.stat[s.area]=p.stat[s.area]||{n:0,c:0}; p.stat[s.area].n++; if(ok)p.stat[s.area].c++;
  const h=p.hist[t]=p.hist[t]||{n:0,c:0,ms:0}; h.n++; if(ok)h.c++; h.ms=(h.ms||0)+Math.min(performance.now()-g.t0,60000);
  g.log.push({q:c.q,a:c.a,you:g.input,ok,src:c.src,st:c.st});
  if(c.src==='card'){ const cd=c.card;
    if(ok){ cd.box++; if(cd.box>=3){ p.cards=p.cards.filter(x=>x!==cd); p.grad++; HG('grad'); g.toast='오답 졸업!'; } else cd.due=t+CARD_GAP[cd.box]; }
    else { cd.box=0; cd.due=t+1; cd.wrong++; } }
  if(c.src==='review'){ const r=g.reviewed[c.st]=g.reviewed[c.st]||{n:0,w:0}; r.n++; if(!ok){r.w++; addCard(p,c);} }
  if(c.src==='new'){
    p.bp=p.bp||{}; const bl=BANK[s.id].length, pos=p.bp[s.id]||0;
    p.bp[s.id]=ok?Math.min(bl-1,pos+(p.streak>=2?2:1)):Math.max(0,pos-2);
    if(ok){ p.streak++; if(p.streak>=GOAL&&p.bp[s.id]>=Math.floor(bl*2/3)&&p.stage<STAGES.length-1){ p.passed[s.id]={due:t+3}; if(p.wr) delete p.wr[s.id]; g.passedNow.push(s.name); HG('pass'); p.stage++; p.streak=0; areaF=null; g.toast=`${s.name} 통과! 다음 단계는 개념 설명부터 시작해요`; } }
    else { p.streak=0; addCard(p,c); p.wr=p.wr||{}; p.wr[s.id]=(p.wr[s.id]||0)+1;
      if(p.wr[s.id]>=CAP(s)){ p.wr[s.id]=0; p.bp[s.id]=0; p.read[s.id]=false; g.restart=`${CAP(s)}개를 틀려서 「${s.name}」을 처음부터 다시 시작해요. 개념부터 다시 봐요.`; g.restarts=(g.restarts||0)+1; } } }
  if(!ok&&c.src!=='retry') g.q.splice(Math.min(g.i+4,g.q.length),0,{src:'retry',q:c.q,a:c.a,st:c.st});
  save(); refreshWrong();
  const b=screen.querySelector('#board'),fb=screen.querySelector('#fb'); b.classList.add(ok?'ok':'no');
  fb.className='fb '+(ok?'ok':'no'); fb.innerHTML=ok?'정답!':(j.msg||`정답은 ${show(c.a)} · 3문제 뒤 다시 나와요`);
  g.lock=true;
  if(!ok){
    g.wrongWait=true;
    screen.querySelector('#tip').innerHTML=g.restart?`<span class="restart">${g.restart}</span>`:`<b>기억할 점</b> ${s.tip}`; g.restart='';
    const hadRestart=/restart/.test(screen.querySelector('#tip').innerHTML);
    screen.querySelector('#pad').outerHTML=`<div id="autoBox"></div><div class="wrongbar"><button class="btn k" id="seeCx">${LI('book-open')}개념 보기</button><button class="btn y" id="goOn">다음 문제${LI('arrow-right')}</button></div>`;
    screen.querySelector('#seeCx').onclick=()=>openFromPlay(s.id);
    screen.querySelector('#goOn').onclick=()=>nextAfterWrong();
    autoGo(hadRestart?AUTO_LONG:AUTO_NO,nextAfterWrong);
    return;
  }
  setTimeout(()=>{ if(G!==g) return; g.lock=false; g.i++; if(g.i>=g.q.length) return finish(); advance(); },350);
}
function mmss(ms){ const s=Math.round(ms/1000); return s<60?`${s}초`:`${Math.floor(s/60)}분 ${s%60}초`; }
function finish(){
  const g=G,p=P(),t=today(); G=null; document.onkeydown=null;
  Object.entries(g.reviewed).forEach(([id,r])=>{ if(p.passed[id]) p.passed[id].due=t+(r.w?3:5); });
  const per={}; g.log.filter(r=>r.src!=='retry').forEach(r=>{ const o=per[r.st]=per[r.st]||{n:0,c:0}; o.n++; if(r.ok)o.c++; });
  Object.entries(per).forEach(([id,o])=>{ const a=p.sst[id]=p.sst[id]||[]; a.push(Math.round(o.c/o.n*100)); if(a.length>3)a.shift(); });
  save(); tab='home'; showTabs(true);
  const n=g.log.length,c=g.log.filter(r=>r.ok).length, wrong=g.log.filter(r=>!r.ok&&r.src!=='retry'), rv=Object.entries(g.reviewed);
  const time=mmss(performance.now()-g.began-g.away);
  setBar(g.title+' 결과');
  screen.innerHTML=`<div class="res">
    <div class="box center"><small class="note">${dlabel(t)} · 풀이 시간 ${time}</small><div class="big">${n?Math.round(c/n*100):0}점</div><p class="note">${n}문제 중 ${c}개 정답 (틀린 문제 다시 풀기 포함)</p></div>
    <div class="grid3"><div class="cell"><b>${wrong.length}</b><span>내일 다시 나올 오답</span></div><div class="cell"><b>${g.passedNow.length}</b><span>통과한 단계</span></div><div class="cell"><b>${p.streak}/${GOAL}</b><span>지금 단계 연속</span></div></div>
    ${g.passedNow.length?`<div class="toast">${g.passedNow.join(', ')} 통과 → 다음: ${STAGES[p.stage].name}</div>`:''}${g.restarts?`<div class="toast warn">틀림 상한에 닿아 「${STAGES[p.stage].name}」을 처음부터 다시 해요</div>`:''}
    ${rv.length?`<div class="box"><h3>단계 복습 결과</h3><div class="list">${rv.map(([id,r])=>`<div><span>${STAGES[IDX[id]].name}</span><span>${r.w?`<span class="x">✕${r.w}</span> → 3일 뒤`:'다 맞음 → 5일 뒤'}</span></div>`).join('')}</div></div>`:''}
    ${wrong.length?`<div class="box"><h3>틀린 문제 <small class="note">오답노트에 저장됨 · ?를 누르면 개념</small></h3><ul class="units in">${wrong.slice(0,8).map(r=>`<li><div class="unit static"><b class="mq">${plain(r.q)} = <span class="ansv">${show(r.a)}</span></b><small>내 답 <span class="x">${r.you.replace('-','−')}</span> · ${STAGES[IDX[r.st]].name}</small></div><button class="qbtn" data-q="${r.st}" aria-label="개념">${Q_ICON}</button></li>`).join('')}</ul></div>`:'<p class="note center">틀린 문제가 없어요.</p>'}
    <div class="btns sp"><button class="btn" id="home">${LI('house')}연산학습으로</button><button class="btn k" id="cards">${LI('notebook-pen')}오답노트 보기</button></div>
  </div>
  <div class="dim" id="dlg"><div class="dialog" role="dialog" aria-labelledby="dt"><h3 id="dt">${LI('bell')}알림</h3><p>문제풀이가 끝났습니다.<br>문제풀이 시간: <b>${time}</b><br>정답: <b>${c} / ${n}</b>${wrong.length?`<br>틀린 ${wrong.length}문제는 내일 다시 나와요.`:''}</p><button id="dok">확인</button></div></div>`;
  screen.querySelector('#dok').onclick=()=>screen.querySelector('#dlg').remove();
  screen.querySelector('#home').onclick=()=>setTab('home');
  screen.querySelector('#cards').onclick=()=>setTab('cards');
  screen.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>openConcept(b.dataset.q,()=>setTab('cards')));
}

